class Base {
public:
  virtual ~Base() {} // Virtual destructor
};

class Derived : public Base {
public:
  ~Derived() override { /* Derived class cleanup */ }
  int derivedMember; //Unique to derived
};

int main() {
  Base* b = new Derived();
  delete b; // Correctly calls Derived::~Derived() if Base::~Base() is virtual
  return 0;
}
